namespace ghidra.app.plugin.core.analysis;

using ghidra.app.util.query;
using ghidra.framework.plugintool;
using docking;
using docking.action;
using docking.action;

public class UpdateAlignmentAction : ToggleDockingAction, AddressAlignmentListener {

	Plugin plugin;
	int alignment;
	FindReferencesTableModel model;

	public UpdateAlignmentAction(Plugin plugin, FindReferencesTableModel model, int alignment) : base("UpdateAlignmentAction"+Integer.toString(alignment), plugin.getName())
    {
		this.plugin = plugin;
		this.alignment = alignment;
		this.model = model;
		
		string[] menuPath = new string[] {"Alignment", Integer.toString(alignment)};
        setPopupMenuData( new MenuData( menuPath ) );
        setMenuBarData( new MenuData( menuPath ) );
		setEnabled(true);
		setSelected(model.getAlignment() == alignment);
		model.addAlignmentListener(this);
	}
	
	/* @Override */
	public void dispose() {
		model.removeAlignmentListener(this);
		base.dispose();
	}

	/* @Override */
    public void actionPerformed(ActionContext context) {
		int currentAlignment = model.getAlignment();
		if (currentAlignment != alignment) {
			model.setAlignment(alignment);
		}
	}
	
	/* @Override */
	public void alignmentChanged() {
		setSelected(model.getAlignment() == alignment);
	}
	
	/* @Override */
	public void alignmentPermissionChanged() {
		setSelected(model.getAlignment() == alignment);
	}
}
